example_solution:
const std = @import("std");
const mem = std.mem;

pub const Nationality = enum {
    englishman,
    japanese,
    norwegian,
    spaniard,
    ukrainian,
};

pub const Color = enum {
    blue,
    green,
    ivory,
    red,
    yellow,
};

pub const Drink = enum {
    coffee,
    milk,
    orange_juice,
    tea,
    water,
};

pub const Hobby = enum {
    reading,
    painting,
    football,
    dancing,
    chess,
};

pub const Pet = enum {
    dog,
    fox,
    horse,
    snails,
    zebra,
};

pub const Solution = struct {
    drinks_water: Nationality,
    owns_zebra: Nationality,
};

pub fn solve(allocator: mem.Allocator) mem.Allocator.Error!Solution {
    _ = allocator;
    return Solution{
        .drinks_water = .norwegian,
        .owns_zebra = .japanese,
    };
}

test_code:
const std = @import("std");
const testing = std.testing;

const zebra_puzzle = @import("zebra_puzzle.zig");
const solve = zebra_puzzle.solve;
const Nationality = zebra_puzzle.Nationality;

test "resident who drinks water" {
    const expected: Nationality = .norwegian;
    const actual = (try solve(testing.allocator)).drinks_water;
    try testing.expectEqual(expected, actual);
}

test "resident who owns zebra" {
    const expected: Nationality = .japanese;
    const actual = (try solve(testing.allocator)).owns_zebra;
    try testing.expectEqual(expected, actual);
}
